from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Find the minimum cost to cover every section with two capped sensor types."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    # The global count caps need never exceed the number required by an all-one-type
    # solution, which also keeps the dynamic program finite.
    max1 = min(k1, sum((d + l1 - 1) // l1 for d in sections))
    max2 = min(k2, sum((d + l2 - 1) // l2 for d in sections))

    # dp[x] is the least cost after covering the sections seen so far with
    # exactly x type-1 sensors. The type-2 count is tracked as a resource cap.
    dp = {(0, 0): 0}
    for d in sections[:n]:
        options = []
        upper = min(max1, (d + l1 - 1) // l1)
        for x in range(upper + 1):
            remain = max(0, d - x * l1)
            y = (remain + l2 - 1) // l2
            if y <= max2:
                options.append((x, y, x * c1 + y * c2))
        nxt = {}
        for (used1, used2), cost in dp.items():
            for x, y, add in options:
                a, b = used1 + x, used2 + y
                if a <= max1 and b <= max2:
                    key = (a, b)
                    value = cost + add
                    if value < nxt.get(key, float("inf")):
                        nxt[key] = value
        dp = nxt
        if not dp:
            return -1
    return min(dp.values()) if dp else -1

from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count numbers whose digit product is divisible by their digit sum."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        length = len(digits)
        answer = 0

        # Fixing the final digit sum lets us track the product modulo that sum.
        for target_sum in range(1, 9 * length + 1):
            @lru_cache(maxsize=None)
            def visit(pos: int, digit_sum: int, product_mod: int, started: bool, tight: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                if digit_sum + 9 * (length - pos) < target_sum:
                    return 0
                if pos == length:
                    return int(digit_sum == target_sum and product_mod == 0 and started)

                limit = digits[pos] if tight else 9
                ways = 0
                for digit in range(limit + 1):
                    next_started = started or digit != 0
                    next_sum = digit_sum + (digit if next_started else 0)
                    if next_started:
                        next_mod = (product_mod * digit) % target_sum if started else digit % target_sum
                    else:
                        next_mod = 1 % target_sum
                    ways += visit(
                        pos + 1,
                        next_sum,
                        next_mod,
                        next_started,
                        tight and digit == limit,
                    )
                return ways

            answer += visit(0, 0, 1 % target_sum, False, True)
        return answer

    return count_up_to(r) - count_up_to(l - 1)

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements for which at least k substrings are reducible to empty."""
    mod = 998244353
    if k <= 0:
        return pow(3, s.count("?"), mod)

    # Prefix parity vectors are equivalent up to toggling all three bits:
    # exactly these equivalent vectors have a difference that is reducible.
    def cls(mask):
        return min(mask, mask ^ 7)

    # A path state stores its current prefix class and the visit counts of
    # the four classes. A good substring is precisely a pair of prefixes in
    # the same class, so its total is determined by these visit counts.
    initial = (1, 0, 0, 0)
    dp = {(0, initial): 1}
    masks = {"A": 1, "B": 2, "C": 4}
    for ch in s:
        ndp = {}
        for (last, counts), ways in dp.items():
            if ch == "?":
                destinations = (c for c in range(4) if c != last)
            else:
                # Prefix parity classes are represented by their smaller mask.
                # Applying a letter toggles its corresponding parity bit.
                dest = cls((last ^ masks[ch]))
                destinations = (dest,)
            for dest in destinations:
                updated = list(counts)
                updated[dest] += 1
                key = (dest, tuple(updated))
                ndp[key] = (ndp.get(key, 0) + ways) % mod
        dp = ndp

    answer = 0
    for (_, counts), ways in dp.items():
        good = sum(x * (x - 1) // 2 for x in counts)
        if good >= k:
            answer = (answer + ways) % mod
    return answer

