from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """ Count the number of beautiful integers in the range [low, high].

    A number is beautiful if it meets both conditions:
    1. The count of even digits equals the count of odd digits
    2. The number is divisible by k

    Args:
        low: Lower bound of the range (inclusive), 0 < low <= high <= 10^9
        high: Upper bound of the range (inclusive)
        k: Divisor to check, 0 < k <= 20

    Returns:
        The count of beautiful integers in the given range
    """
    def up_to(limit: int) -> int:
        if limit <= 0:
            return 0
        digits = tuple(map(int, str(limit)))

        @lru_cache(None)
        def dp(pos: int, remainder: int, balance: int, started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and remainder == 0 and balance == 0)

            max_digit = digits[pos] if tight else 9
            total = 0
            for digit in range(max_digit + 1):
                next_tight = tight and digit == max_digit
                if not started and digit == 0:
                    total += dp(pos + 1, remainder, balance, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    total += dp(
                        pos + 1,
                        (remainder * 10 + digit) % k,
                        next_balance,
                        True,
                        next_tight,
                    )
            return total

        return dp(0, 0, 0, False, True)

    return up_to(high) - up_to(low - 1)

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """Return the minimum edits needed to split s into k semi-palindromes.

    A substring is a semi-palindrome when its length is at least two and,
    for some proper positive divisor d of its length, every sequence of
    characters at positions congruent modulo d is a palindrome.
    """
    n = len(s)
    inf = n + 1

    # change_cost[left][right] is the cheapest way to turn that inclusive
    # substring into a semi-palindrome.
    change_cost = [[inf] * n for _ in range(n)]
    for left in range(n):
        for length in range(2, n - left + 1):
            best = inf
            for d in range(1, length):
                if length % d:
                    continue
                group_len = length // d
                edits = 0
                for offset in range(d):
                    for t in range(group_len // 2):
                        a = left + offset + t * d
                        b = left + offset + (group_len - 1 - t) * d
                        if s[a] != s[b]:
                            edits += 1
                if edits < best:
                    best = edits
            change_cost[left][left + length - 1] = best

    # dp[p][end] is the minimum cost to partition s[:end] into p pieces.
    dp = [[inf] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for pieces in range(1, k + 1):
        min_end = 2 * pieces
        max_end = n - 2 * (k - pieces)
        for end in range(min_end, max_end + 1):
            for start in range(2 * (pieces - 1), end - 1):
                if dp[pieces - 1][start] == inf:
                    continue
                cost = change_cost[start][end - 1]
                candidate = dp[pieces - 1][start] + cost
                if candidate < dp[pieces][end]:
                    dp[pieces][end] = candidate
    return dp[k][n]

