from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """ Given N sections to monitor on a conveyor belt, find the minimum cost to monitor all sections using two types of sensors.

    Each section has a length in meters that needs to be monitored. There are two types of sensors available:
    - Type 1: Can monitor L1 meters, costs C1 per sensor, and you can use at most K1 sensors
    - Type 2: Can monitor L2 meters, costs C2 per sensor, and you can use at most K2 sensors

    Sensors can overlap and can monitor more than the required length. For example, to monitor a 5-meter section,
    you could use one 4-meter sensor and one 2-meter sensor (total coverage: 6 meters).

    Args:
        n: Number of sections to monitor (1 <= n <= 100)
        sections: List of section lengths D_i in meters (1 <= D_i <= 10^5)
        sensor1: Tuple (L1, C1, K1) - length, cost, and max count for type 1 sensors
        sensor2: Tuple (L2, C2, K2) - length, cost, and max count for type 2 sensors

    Returns:
        The minimum total cost to monitor all sections, or -1 if impossible.
    """
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    # A state records the total sensors of each type used. For each section,
    # only the least number of type 2 sensors for each type 1 count can help.
    states = {(0, 0): 0}
    for demand in sections[:n]:
        options = []
        for x in range(min(k1, (demand + l1 - 1) // l1) + 1):
            remaining = max(0, demand - x * l1)
            y = (remaining + l2 - 1) // l2
            if y <= k2:
                options.append((x, y, x * c1 + y * c2))
        if not options:
            return -1
        updated = {}
        for (used1, used2), cost in states.items():
            for x, y, added in options:
                total1, total2 = used1 + x, used2 + y
                if total1 <= k1 and total2 <= k2:
                    key = (total1, total2)
                    candidate = cost + added
                    if candidate < updated.get(key, float("inf")):
                        updated[key] = candidate
        if not updated:
            return -1
        # Discard states that use at least as many sensors of both types and
        # cost at least as much as another state.
        ordered = sorted(updated.items(), key=lambda item: (item[0][0], item[0][1], item[1]))
        states = {}
        for (a, b), cost in ordered:
            dominated = False
            for (pa, pb), pcost in states.items():
                if pa <= a and pb <= b and pcost <= cost:
                    dominated = True
                    break
            if not dominated:
                states[(a, b)] = cost
    return min(states.values(), default=-1)

MOD = 998244353


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor-count scores over all good sequences."""
    primes = [p for p in (2, 3, 5, 7, 11, 13) if p <= m]
    r = len(primes)

    # A block contributes the product of the selected prime valuations of one
    # element in [1, m].
    block_sum = {}
    for mask in range(1, 1 << r):
        total = 0
        for original in range(1, m + 1):
            term = 1
            for j, p in enumerate(primes):
                if mask >> j & 1:
                    value = original
                    exponent = 0
                    while value % p == 0:
                        value //= p
                        exponent += 1
                    term *= exponent
            total += term
        block_sum[mask] = total % MOD

    # T_b = sum_{k=b}^n (k)_b m^(k-b), the total weight from assigning
    # b distinct sequence positions to the blocks.
    t = [0] * (r + 1)
    if m == 1:
        t[0] = n % MOD
        for b in range(1, r + 1):
            if n >= b:
                product = 1
                for j in range(b + 1):
                    product = product * ((n + 1 - j) % MOD) % MOD
                t[b] = product * pow(b + 1, MOD - 2, MOD) % MOD
    else:
        # Taylor coefficients at x=m of G(x)=sum_{k=1}^n x^k
        # = (x^(n+1)-x)/(x-1). Coefficient b is G^(b)(m)/b!.
        N = n + 1
        power = [0] * (r + 1)
        falling_over_fact = 1
        for j in range(r + 1):
            if j:
                falling_over_fact = (
                    falling_over_fact * ((N - j + 1) % MOD) % MOD
                    * pow(j, MOD - 2, MOD) % MOD
                )
            power[j] = falling_over_fact * pow(m, N - j, MOD) % MOD

        inverse = [0] * (r + 1)
        inverse[0] = pow(m - 1, MOD - 2, MOD)
        for j in range(1, r + 1):
            inverse[j] = -inverse[j - 1] * inverse[0] % MOD

        for b in range(r + 1):
            coefficient = 0
            for j in range(b + 1):
                numerator = power[j] - (m if j == 1 else 0)
                coefficient = (coefficient + numerator * inverse[b - j]) % MOD
            factorial = 1
            for j in range(2, b + 1):
                factorial = factorial * j % MOD
            t[b] = coefficient * factorial % MOD

    answer = t[0]  # Empty prime subset: sum of m^k for 1 <= k <= n.

    # Enumerate set partitions. Each block means its prime factors' exponents
    # are drawn from the same element position.
    for mask in range(1, 1 << r):
        partitions = []

        def build_partitions(remaining, chosen):
            if remaining == 0:
                partitions.append(chosen)
                return
            bit = remaining & -remaining
            rest = remaining ^ bit
            subset = rest
            while True:
                block = subset | bit
                build_partitions(remaining ^ block, chosen + [block])
                if subset == 0:
                    break
                subset = (subset - 1) & rest

        build_partitions(mask, [])
        for partition in partitions:
            factor = t[len(partition)]
            for block in partition:
                factor = factor * block_sum[block] % MOD
            answer = (answer + factor) % MOD

    return answer

