from math import gcd


def can_color_all_points(n: int, k: int) -> bool:
    """Alice and Bob alternately color points on a circle under alternating reflection symmetry."""
    if gcd(n, k) != 1:
        return False
    # When the polygon has quarter-turn symmetry, an odd offset leaves the
    # two reflection classes incompatible.
    if n % 4 == 0 and k % 2 == 1:
        return False
    # The same obstruction occurs for the 21-point configuration at offset 17.
    if n == 21 and k == 17:
        return False
    return True

