MOD = 998244353


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor-count scores over all good sequences."""
    primes = [p for p in (2, 3, 5, 7, 11, 13) if p <= m]
    r = len(primes)

    block_sum = {}
    for mask in range(1, 1 << r):
        total = 0
        for original in range(1, m + 1):
            term = 1
            for j, p in enumerate(primes):
                if mask >> j & 1:
                    value = original
                    exponent = 0
                    while value % p == 0:
                        value //= p
                        exponent += 1
                    term *= exponent
            total += term
        block_sum[mask] = total % MOD

    # T_b = sum_{k=b}^n (k)_b m^(k-b).
    t = [0] * (r + 1)
    if m == 1:
        t[0] = n % MOD
        for b in range(1, r + 1):
            if n >= b:
                product = 1
                for j in range(b + 1):
                    product = product * ((n + 1 - j) % MOD) % MOD
                t[b] = product * pow(b + 1, MOD - 2, MOD) % MOD
    else:
        # Taylor coefficients of G(x)=sum_{k=1}^n x^k
        # = (x^(n+1)-x)/(x-1). Coefficient b equals G^(b)(m)/b!.
        N = n + 1
        power = [0] * (r + 1)
        falling_over_fact = 1
        for j in range(r + 1):
            if j:
                falling_over_fact = (
                    falling_over_fact * ((N - j + 1) % MOD) % MOD
                    * pow(j, MOD - 2, MOD) % MOD
                )
            power[j] = falling_over_fact * pow(m, N - j, MOD) % MOD

        inverse = [0] * (r + 1)
        inverse[0] = pow(m - 1, MOD - 2, MOD)
        for j in range(1, r + 1):
            inverse[j] = -inverse[j - 1] * inverse[0] % MOD

        for b in range(r + 1):
            coefficient = 0
            for j in range(b + 1):
                numerator = power[j]
                if j == 0:
                    numerator -= m
                elif j == 1:
                    numerator -= 1
                coefficient = (coefficient + numerator * inverse[b - j]) % MOD
            factorial = 1
            for j in range(2, b + 1):
                factorial = factorial * j % MOD
            t[b] = coefficient * factorial % MOD

    answer = t[0]
    for mask in range(1, 1 << r):
        partitions = []

        def build_partitions(remaining, chosen):
            if remaining == 0:
                partitions.append(chosen)
                return
            bit = remaining & -remaining
            rest = remaining ^ bit
            subset = rest
            while True:
                block = subset | bit
                build_partitions(remaining ^ block, chosen + [block])
                if subset == 0:
                    break
                subset = (subset - 1) & rest

        build_partitions(mask, [])
        for partition in partitions:
            factor = t[len(partition)]
            for block in partition:
                factor = factor * block_sum[block] % MOD
            answer = (answer + factor) % MOD

    return answer

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353
    """
    mod = 998244353

    # Transfer across the shorter side to keep the row-state space small.
    if H < W:
        H, W = W, H
        grid = ["".join(grid[r][c] for r in range(len(grid))) for c in range(len(grid[0]))]

    fixed_rows = [
        [-1 if ch == "?" else int(ch) - 1 for ch in row]
        for row in grid
    ]

    pow3 = [1] * W
    for i in range(1, W):
        pow3[i] = pow3[i - 1] * 3

    def make_states(fixed):
        states = []

        def build(col, prev, code, vals):
            if col == W:
                states.append((code, tuple(vals)))
                return
            forced = fixed[col]
            choices = range(3) if forced < 0 else (forced,)
            for color in choices:
                if color == prev:
                    continue
                vals.append(color)
                build(col + 1, color, code + color * pow3[col], vals)
                vals.pop()

        build(0, -1, 0, [])
        return states

    rows = [make_states(row) for row in fixed_rows]
    if not rows[0]:
        return 0

    dp = {code: 1 for code, _ in rows[0]}
    for r in range(1, H):
        if not rows[r]:
            return 0
        nxt = {}
        valid_codes = {code for code, _ in rows[r]}
        fixed = fixed_rows[r]
        for code, above in rows[r - 1]:
            ways = dp.get(code, 0)
            if not ways:
                continue

            def extend(col, prev, new_code):
                if col == W:
                    if new_code in valid_codes:
                        nxt[new_code] = (nxt.get(new_code, 0) + ways) % mod
                    return
                forced = fixed[col]
                choices = range(3) if forced < 0 else (forced,)
                top = above[col]
                for color in choices:
                    if color == top or color == prev:
                        continue
                    extend(col + 1, color, new_code + color * pow3[col])

            extend(0, -1, 0)
        dp = nxt
        if not dp:
            return 0

    return sum(dp.values()) % mod

