def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions inside the rectangle."""
    def count_parity(lo: int, hi: int, parity: int) -> int:
        first = lo if lo % 2 == parity else lo + 1
        return max(0, (hi - first + 1) // 2)

    def primitive_twice(z: int, height: int) -> int:
        if z <= 0:
            return 0
        if z < height:
            return z * z
        return 2 * height * z - height * height

    def below_area_twice(x_parity: int, lo: int, hi: int) -> int:
        height = hi - lo
        a = 2 if x_parity == 0 else 1
        return primitive_twice(a - lo, height) - primitive_twice(a - lo - 1, height)

    def black_below(xp: int, jp: int) -> bool:
        # Crossing each horizontal band also crosses a diagonal in odd x stripes.
        return (xp + jp + xp * jp) % 2 == 0

    def full_band_sum(jlo: int, jhi: int, xlo: int, xhi: int) -> int:
        total = 0
        for xp in (0, 1):
            nx = count_parity(xlo, xhi, xp)
            for jp in (0, 1):
                nj = count_parity(jlo, jhi, jp)
                if nx and nj:
                    below = below_area_twice(xp, 0, 2)
                    black = below if black_below(xp, jp) else 4 - below
                    total += nx * nj * black
        return total

    j0 = B // 2
    j1 = (D - 1) // 2
    total = 0
    xlo, xhi = A, C
    if j0 == j1:
        lo, hi = B - 2 * j0, D - 2 * j0
        for xp in (0, 1):
            nx = count_parity(xlo, xhi, xp)
            if nx:
                below = below_area_twice(xp, lo, hi)
                black = below if black_below(xp, j0 % 2) else 2 * (hi - lo) - below
                total += nx * black
        return total

    lo, hi = B - 2 * j0, 2
    for xp in (0, 1):
        nx = count_parity(xlo, xhi, xp)
        if nx:
            below = below_area_twice(xp, lo, hi)
            black = below if black_below(xp, j0 % 2) else 2 * (hi - lo) - below
            total += nx * black

    total += full_band_sum(j0 + 1, j1, xlo, xhi)

    lo, hi = 0, D - 2 * j1
    for xp in (0, 1):
        nx = count_parity(xlo, xhi, xp)
        if nx:
            below = below_area_twice(xp, lo, hi)
            black = below if black_below(xp, j1 % 2) else 2 * (hi - lo) - below
            total += nx * black
    return total

