from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """ Count the number of beautiful integers in the range [low, high].

    A number is beautiful if it meets both conditions:
    1. The count of even digits equals the count of odd digits
    2. The number is divisible by k

    Args:
        low: Lower bound of the range (inclusive), 0 < low <= high <= 10^9
        high: Upper bound of the range (inclusive)
        k: Divisor to check, 0 < k <= 20

    Returns:
        The count of beautiful integers in the given range

    >>> count_beautiful_integers(10, 20, 3)
    2
    >>> count_beautiful_integers(1, 10, 1)
    1
    >>> count_beautiful_integers(5, 5, 2)
    0
    """
    def count_at_most(limit: int) -> int:
        if limit <= 0:
            return 0

        digits = tuple(map(int, str(limit)))

        @lru_cache(None)
        def dp(pos: int, diff: int, remainder: int, started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and diff == 0 and remainder == 0)

            top = digits[pos] if tight else 9
            total = 0
            for digit in range(top + 1):
                next_tight = tight and digit == top
                if not started and digit == 0:
                    total += dp(pos + 1, diff, remainder, False, next_tight)
                else:
                    next_diff = diff + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += dp(pos + 1, next_diff, next_remainder, True, next_tight)
            return total

        return dp(0, 0, 0, False, True)

    return count_at_most(high) - count_at_most(low - 1)

from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers whose digit product is divisible by digit sum."""
    def upto(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        total = 0
        # A number with digit sum s is beautiful exactly when its digit
        # product is 0 modulo s.
        for target in range(1, 9 * len(digits) + 1):
            @lru_cache(None)
            def dp(pos: int, digit_sum: int, residue: int, started: bool, tight: bool) -> int:
                if digit_sum > target:
                    return 0
                if pos == len(digits):
                    return int(started and digit_sum == target and residue == 0)
                limit = digits[pos] if tight else 9
                result = 0
                for d in range(limit + 1):
                    new_started = started or d != 0
                    new_sum = digit_sum + (d if new_started else 0)
                    if new_sum > target:
                        continue
                    new_residue = residue
                    if new_started:
                        new_residue = (residue * d) % target if started else d % target
                    result += dp(pos + 1, new_sum, new_residue, new_started,
                                tight and d == limit)
                return result
            total += dp(0, 0, 1 % target, False, True)
        return total

    return upto(r) - upto(l - 1)

