        def visit(state):
            if left <= state[0] <= right and bottom <= state[1] <= top and state not in distances:
                distances[state] = d + 1
                queue.append(state)

        if k:
            visit((i, j, k - 1))
        if k + 1 < K:
            visit((i, j, k + 1))

        horizontal = (i - j) % 2 == 0
        if horizontal:
            visit((i + 1, j, 0))
            visit((i - 1, j, K - 1))
            if k == K - 1:
                for q in range(K):
                    visit((i, j + 1, q))
            if k == 0:
                for q in range(K):
                    visit((i, j - 1, q))
        else:
            if k == K - 1:
                for q in range(K):
                    visit((i + 1, j, q))
            if k == 0:
                for q in range(K):
                    visit((i - 1, j, q))
            visit((i, j + 1, 0))
            visit((i, j - 1, K - 1))

    return cell_distance

