from typing import List

MOD = 998244353
ROOT = 3


def _ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(ROOT, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            for i in range(start, start + half):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def _multiply_truncated(a, b, limit):
    full_len = len(a) + len(b) - 1
    size = 1
    while size < full_len:
        size <<= 1
    fa = a + [0] * (size - len(a))
    fb = b + [0] * (size - len(b))
    _ntt(fa, False)
    _ntt(fb, False)
    for i in range(size):
        fa[i] = fa[i] * fb[i] % MOD
    _ntt(fa, True)
    return fa[:min(full_len, limit)]


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count valid uppercase strings of lengths 1 through K with per-letter caps."""
    if not any(C):
        return 1
    if all(c >= K for c in C):
        return (pow(26, K + 1, MOD) - 26) * pow(25, MOD - 2, MOD) % MOD

    inv_fact = [1] * (K + 1)
    for i in range(1, K + 1):
        inv_fact[i] = inv_fact[i - 1] * pow(i, MOD - 2, MOD) % MOD

    poly = [1]
    for cap in C:
        cap = min(cap, K)
        if cap == 0:
            continue
        poly = _multiply_truncated(poly, inv_fact[:cap + 1], K + 1)

    fact = 1
    answer = 0
    for n in range(1, K + 1):
        fact = fact * n % MOD
        if n < len(poly):
            answer = (answer + fact * poly[n]) % MOD
    return answer

